{
  const INK="#2a2630", M="#8c919b", DD="#4a4d54", BR="#c9932f";
  const pauldron = (x0, y0, w, h, flip, [OR,ORL,ORD]) => {
    const X = u => flip ? x0 + w - u*w : x0 + u*w, Y = v => y0 + v*h;
    const P = pts => "M" + pts.map(([u,v])=>`${X(u).toFixed(1)} ${Y(v).toFixed(1)}`).join(" L") + " Z";
    const q = (pts,f,sw=2.4) => `<path d="${P(pts)}" fill="${f}" stroke="${INK}" stroke-width="${sw}" stroke-linejoin="round"/>`;
    const ln = (pts,c,sw) => `<path d="M${pts.map(([u,v])=>`${X(u).toFixed(1)} ${Y(v).toFixed(1)}`).join(" L")}" fill="none" stroke="${c}" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"/>`;
    const riv = (u,v) => `<circle cx="${X(u).toFixed(1)}" cy="${Y(v).toFixed(1)}" r="1.7" fill="${BR}" stroke="${INK}" stroke-width="1"/>`;
    return q([[.03,.62],[.1,.16],[.42,0],[.8,.08],[.98,.36],[.97,.6]], OR)                       // 上面的大甲片（稜角）
      + ln([[.14,.2],[.42,.06],[.76,.13]], ORL, 2.6) + ln([[.42,.04],[.5,.56]], ORD, 1.6)           // 亮面、中間的稜線
      + q([[.0,.58],[1,.56],[.97,.76],[.04,.78]], DD) + ln([[.04,.6],[.96,.58]], BR, 1.6)           // 第一層甲片（黃銅邊）
      + q([[.04,.76],[.97,.74],[.93,.95],[.09,.98]], M) + ln([[.08,.78],[.93,.76]], BR, 1.6)        // 第二層甲片
      + riv(.15,.67)+riv(.5,.66)+riv(.85,.66)+riv(.2,.87)+riv(.5,.86)+riv(.8,.86)
      + `<path d="M${X(.5)} ${Y(.24)} l3 3 l-3 3 l-3 -3 z" fill="${BR}" stroke="${INK}" stroke-width="1.2"/>`;   // 黃銅飾釘
  };
  const STEEL = ["#4a4d54","#7b808a","#33363c"];   // 深鋼＋黃銅（大爺 10-22 選的）
  const P = MONSTER_LOOK.dwarf.parts;
  const asSvg = g => `<svg x="32" y="6" width="76" height="76" viewBox="0 0 100 100" overflow="visible"><g transform="scale(1.3158) translate(-32 -6)">${g}</g></svg>`;
  const place = g => `<g transform="translate(73 50) scale(.69) translate(-76 -86)">${g}</g>`;
  const k = .213, body = `<g transform="translate(${70-356*k} ${143-702*k}) scale(${k})">${DWARF_ARMOR_ART}</g>`;
  const full = (hurt, id) => `<defs><clipPath id="${id}"><path d="M-40 -60 H180 V36 Q73 42 -40 36 Z"/></clipPath></defs>`
    + body + `<g clip-path="url(#${id})">${place(asSvg(P.headTop(hurt)))}</g>`
    + pauldron(6,33,50,42,false,STEEL) + pauldron(93,30,39,40,true,STEEL) + place(asSvg(P.beard)) + place(P.chest);
  const face = `<svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><g transform="translate(50 56) scale(1.9) translate(-73 -40)">${full(false,"dwarf-collar-face")}</g></svg>`;
  MONSTER_LOOK.dwarf_armored = {kind:"dwarf_armored", size:"大型", art:full(false,"dwarf-collar"), face,
    render:o=>undeadStaticDollSVG({...o, look:{...o.look, art: (o.down||o.anim?.k==="hurt") ? full(true,"dwarf-collar-hurt") : full(false,"dwarf-collar")}})};
}
